"""Bounded PDF cache: only files generated by this plugin are ever removed."""

from __future__ import annotations

import os
import time
import uuid
from pathlib import Path

MAX_CACHE_BYTES = 256 * 1024 * 1024
MAX_PDF_BYTES = 32 * 1024 * 1024


def save_pdf(data: bytes, directory: Path, retention_hours: int) -> Path:
    if not data.startswith(b"%PDF-"):
        raise ValueError("浏览器没有返回有效的 PDF 文件头")
    if len(data) > MAX_PDF_BYTES:
        raise ValueError("PDF 超过 32 MiB，改为文本回退")
    directory = directory.resolve()
    directory.mkdir(parents=True, exist_ok=True)
    cutoff = time.time() - retention_hours * 3600
    files: list[tuple[float, int, Path]] = []
    for path in directory.glob("reply-*.pdf"):
        if path.is_symlink() or path.resolve().parent != directory:
            continue
        try:
            stat = path.stat()
            if stat.st_mtime < cutoff:
                path.unlink()
            else:
                files.append((stat.st_mtime, stat.st_size, path))
        except FileNotFoundError:
            continue
    # Don't remove a freshly generated file: it may still be uploading.
    # Reject new cache writes instead of evicting another in-flight reply.
    if sum(size for _, size, _ in files) + len(data) > MAX_CACHE_BYTES:
        raise ValueError("PDF 缓存达到 256 MiB，请清理或降低保留时间")
    filename = f"reply-{uuid.uuid4().hex}.pdf"
    destination = directory / filename
    temporary = directory / (filename + ".tmp")
    try:
        with temporary.open("xb") as stream:
            stream.write(data)
        os.replace(temporary, destination)
    finally:
        temporary.unlink(missing_ok=True)
    return destination
